import { z } from 'zod';

/**
 * The persisted enum shapes for the SQLite entities — and, since every one of
 * them also travels to the UI on a run / item / member projection, the wire
 * contract for those enums too.
 *
 * Declared as zod enums carrying `.meta({ id })` so they land as NAMED
 * components in the daemon's OpenAPI document, which is what makes the
 * renderer's generated client (`apps/ui/src/renderer/autogenerated`) expose one
 * union type per enum instead of an inline copy per response.
 */

export const RUN_STATUSES = [
  'pending',
  'running',
  'completed',
  'failed',
  'cancelled',
] as const;

export const RunStatusSchema = z.enum(RUN_STATUSES).meta({ id: 'RunStatus' });
export type RunStatus = z.infer<typeof RunStatusSchema>;

/**
 * Statuses a run never leaves. `pending` and `running` are the live ones;
 * everything else is settled.
 *
 * Derived from {@link RUN_STATUSES} by exclusion rather than listed
 * separately, so adding a status forces a decision here instead of silently
 * defaulting to "not terminal" — which would make a settled run look live.
 */
const LIVE_RUN_STATUSES: ReadonlySet<RunStatus> = new Set<RunStatus>([
  'pending',
  'running',
]);

/** Whether a run has settled and will never change status on its own again. */
export function isTerminalRunStatus(status: RunStatus): boolean {
  return !LIVE_RUN_STATUSES.has(status);
}

/**
 * How a run came by its project when it was created: chosen (`explicit`, a
 * project or deliberately none), its task card's, the nearest project folder
 * above the one it works in, or nothing found (`none`).
 */
export const PROJECT_SOURCES = ['explicit', 'card', 'folder', 'none'] as const;
export type ProjectSource = (typeof PROJECT_SOURCES)[number];

/**
 * What an analysis chat is for: the user's own "Analyze thread" (`review`;
 * null on rows written before purposes) or a hidden lessons reflection.
 */
export const ANALYSIS_PURPOSES = ['review', 'lessons'] as const;
export type AnalysisPurpose = (typeof ANALYSIS_PURPOSES)[number];

/** A member may additionally be `skipped` — it was never started before the run settled. */
export const NodeStatusSchema = z
  .enum([...RUN_STATUSES, 'skipped'])
  .meta({ id: 'NodeStatus' });
export type NodeStatus = z.infer<typeof NodeStatusSchema>;

/**
 * Conversation item kind — the normalized transcript taxonomy (a plain TEXT
 * column, so the `safe: true` schema sync needs no migration). `message`
 * carries user and assistant text (disambiguated by `Item.role`);
 * `usage`/`status`/`attachment` are defined here for the event model and
 * forward-compat though only a subset is emitted. `approval_request` is an
 * `ask`-mode agent's paused tool call awaiting a verdict; `approval_verdict` records
 * the user's answer, closing the pair for reconnect replay.
 *
 * The call kinds: `call_started` (a caller invoked call_agent — attributed to
 * the CALLER member), `call_result` (the call's envelope settled — also the
 * caller's), and `await_collected` (an async result was picked up via
 * await_agent). The callee's own turn streams as regular items under the
 * callee's member id. `call_question` (a call-initiated callee raised
 * AskUserQuestion — parked, awaiting the caller) and `call_answer` (how it
 * resolved: answered via answer_agent, TTL timeout, or orphaned by the caller
 * ending) are attributed to the CALLER member like the other call kinds. `call_answer`
 * with `outcome: 'message'` is the caller's `message_agent`: a message sent
 * into a RUNNING call with no question behind it.
 *
 * `task_list` is one announcement about the agent's OWN task list — the todo
 * list the CLI keeps while it works. Persisted rather than kept live-only
 * because a reopened chat must show the list as it stands, and the list only
 * exists as the sum of its announcements: two of the three shapes on the wire
 * are patches, so a client that missed one cannot reconstruct the rest.
 *
 * `shell_open` and `shell_info` are the two ends of a BACKGROUND SHELL — a
 * command the agent detached, whose launching tool call returned within the
 * second while the command ran on for minutes. Neither renders; both exist so a
 * reader can say which tool calls are still running on the machine.
 *
 * `shell_info` is the CLOSE, and it is the only end signal such a command has:
 * measured on claude 2.1.237, the CLI reports the completion to the MODEL out of
 * band and to the conversation as a sentence the agent writes, so a reader
 * folding "what is running" out of tool calls alone lists it forever. Persisted
 * rather than streamed for the same reason `task_list` is — a reopened chat
 * replays the transcript, and an ephemeral end would show every past background
 * command as running again.
 *
 * `shell_open` is the OPEN, and it shipped as no row at all on the reasoning
 * that the start is already in the transcript as the tool call that detached it.
 * The call is; the DETACHMENT is not. Which tool calls a CLI put in the
 * background is a fact the daemon reads off that CLI's own structured frames,
 * and it was leaving the renderer to recover it by matching the CLI's English —
 * the announcement it writes back to a detached launch. That match is
 * deliberately strict, because a loose one promotes a foreground command whose
 * OUTPUT quotes the sentence into a shell nothing can ever close, so it misses
 * by design and every miss put the daemon's `shellsOpen` count (which counts
 * exactly these events) over a transcript naming fewer commands than it. REPORTED
 * as a sidebar row reading `working · waiting on background work` beside a header
 * counting zero shells — one question, two answers, from the structured reading
 * and the prose reading of the same launch. The row carries what the daemon
 * knows, so the count and the list are now two views of one set.
 *
 * `unanswerable` closes an `approval_request` that can never be answered now:
 * its turn settled while the request was still pending, so the card on screen
 * is a dead control. The daemon says so explicitly rather than leaving the
 * renderer to infer staleness from a settled turn — an inference that has no
 * way to distinguish a request the CLI abandoned from one still in flight.
 *
 * `report_findings` is a list of code-review findings an agent handed the APP
 * to draw — through geniro's own MCP tool, rather than printing them as prose
 * a transcript can only show as prose. The payload IS the card: the tool call
 * answers with a receipt alone, deliberately, so the findings never re-enter
 * the model's context, which leaves this row as the only place they exist.
 * Persisted rather than streamed for `task_list`'s reason — a reopened chat
 * replays the transcript, and a card that lived only on the wire would be gone
 * from every conversation the moment it was closed.
 *
 * `show_chart` is the second row of that same RENDER family, and everything
 * said about `report_findings` above holds unchanged — the payload is the card,
 * the call answers with a receipt, the row is the only place the data exists.
 * What is its own: the payload is POSITIONAL. Every series holds one value per
 * entry of `labels`, aligned by index, so a reader that drops or reorders
 * either list silently re-attributes measurements instead of failing.
 *
 * `show_metrics` is a SCORECARD — a handful of headline figures with their
 * changes, the row an agent reaches for when it has measured a few things and
 * would otherwise write them into a sentence. Everything said above holds; what
 * is its own is that every figure arrives ALREADY FORMATTED, as a string. Only
 * the agent knows whether `0.82` should read `82%` and whether `1258291` is
 * `1.2 MB` or `1,258,291`, so formatting host-side would be guessing — this row
 * displays and never computes. The one thing the host cannot infer is whether a
 * change is good news: lower is better for a latency and worse for a coverage,
 * so the SENTIMENT is stated by the agent rather than read off the sign.
 *
 * `show_comparison` is a DECISION TABLE: several options judged against the
 * same criteria, with a recommendation. Alone in this family it has to justify
 * itself against markdown, since a table RENDERS in this transcript — it earns
 * its place on the two things a table cannot hold, a per-cell VERDICT that makes
 * the winning column visibly greener and a NAMED recommendation. Its cells are
 * POSITIONAL against `options`, the chart's hazard again and handled the same
 * way.
 *
 * `show_gallery` is PICTURES: several images shown as a grid that opens into
 * the full-screen viewer. Alone in this family its payload names FILES rather
 * than carrying its own content — the daemon stores the paths and never opens
 * them, and the renderer resolves each through the same image route a markdown
 * image already uses. Its line is against markdown rather than against a
 * sibling: ONE picture is a markdown image and reads better inline, while this
 * is for a SET the reader can step between.
 *
 * `show_artifact` is a PAGE: a self-contained HTML document the agent wrote,
 * shown in a panel of its own and openable full-screen. It carries what the six
 * above cannot — a layout the agent DESIGNED, and interaction, since the page
 * runs its own script inside a sandboxed frame. Two things are its own. Like the
 * gallery its payload names something stored elsewhere rather than carrying it
 * (the document is a file; the row holds the id, the version, the title and the
 * key that opens it), and alone in this family it is REVISABLE — publishing the
 * same `artifactId` again writes a new row naming a higher version rather than a
 * second artifact, which is what lets a plan stay current as the work moves.
 *
 * `action` is a BUTTON an agent published (`publish_action`), and
 * `action_outcome` is everything that happens to one afterwards: a press, a
 * removal, a dismissal. Both are append-only — a button's state is never an
 * edit of its row but the newest outcome naming its seq — and the daemon folds
 * the pair into the live set it serves on run state (`ChatActionsService`), so
 * no client derives "still pressable" from the window of rows it holds.
 *
 * `team_note` is one note a team agent wrote to the run's shared team
 * notes (`team_note`), readable by every agent of the run (`team_notes`).
 * Append-only like the action pair: a correction is a newer note naming the
 * older one's seq in `supersedes`, and readers fold the pair.
 *
 * `run_outcome` is where one pull request of a team run ended up, recorded
 * by a member (`record_outcome`). Append-only per pull request: the newest row
 * naming a pull request is its outcome, and an earlier one stays as history.
 *
 * `lessons` is the lessons a hidden reflection proposed about this thread
 * (`propose_lessons`), written into the thread it read; `lesson_outcome` is
 * the user's save or reject of one of them, append-only like the action pair.
 */
export const ItemKindSchema = z
  .enum([
    'message',
    'reasoning',
    'tool_call',
    'tool_result',
    'turn_complete',
    'turn_cancelled',
    'system',
    'error',
    'status',
    'approval_request',
    'approval_verdict',
    'unanswerable',
    'call_started',
    'call_result',
    'await_collected',
    'call_question',
    'call_answer',
    'subagent_info',
    'workflow_info',
    'task_list',
    'shell_open',
    'shell_info',
    'report_findings',
    'show_chart',
    'show_metrics',
    'show_comparison',
    'show_gallery',
    'show_artifact',
    'recommendations',
    'recommendation_outcome',
    'action',
    'action_outcome',
    'team_note',
    'run_outcome',
    'stage_change',
    'thread_outcome',
    'lessons',
    'lesson_outcome',
  ])
  .meta({ id: 'ItemKind' });
export type ItemKind = z.infer<typeof ItemKindSchema>;

/**
 * A CLI coding agent the daemon can drive headlessly (M2: one at a time).
 *
 * Declared as a value object so an agent is NAMED at every use site
 * (`AgentKind.CursorAgent`) rather than spelled as a bare string a typo turns
 * into a silently unmatched branch. The schema is derived FROM it, so the
 * vocabulary cannot drift from the names, and the shape deliberately mirrors
 * the `AgentKind` the renderer already receives in `autogenerated/` — both
 * sides of the wire spell an agent the same way.
 */
export const AgentKind = {
  Claude: 'claude',
  CursorAgent: 'cursor-agent',
  Codex: 'codex',
} as const;

export const AgentKindSchema = z.enum(AgentKind).meta({ id: 'AgentKind' });
export type AgentKind = z.infer<typeof AgentKindSchema>;
